class Solution {
public:
    vector<int> dailyTemperatures(vector<int>& temperatures) {
        int n = temperatures.size();
        vector<int> answer(n, 0);
        vector<int> st;               // stack of indices, decreasing temperatures
        st.reserve(n);
        for (int i = n - 1; i >= 0; --i) {
            while (!st.empty() && temperatures[st.back()] <= temperatures[i]) {
                st.pop_back();
            }
            if (!st.empty()) {
                answer[i] = st.back() - i;
            }
            // else answer[i] stays 0
            st.push_back(i);
        }
        return answer;
    }
};
